#!/usr/bin/env node
/* Reconciles phase-one source IDs with JSON lines emitted by latency runner. */
const fs=require('node:fs');
const [inventoryFile,runnerFile,outFile]=process.argv.slice(2);
if(!inventoryFile||!runnerFile||!outFile)throw Error('usage: node interaction_inventory_reconcile.cjs inventory.json runner.log output.json');
const inventory=JSON.parse(fs.readFileSync(inventoryFile,'utf8'));
const reports=[];for(const line of fs.readFileSync(runnerFile,'utf8').split(/\r?\n/)){const at=line.indexOf('{');if(at<0)continue;try{const x=JSON.parse(line.slice(at)),report=x.report||x;if(Array.isArray(report.seenControls))reports.push(report);}catch{}}
const seen=new Set(reports.flatMap(r=>r.seenControls||[])),fired=new Set(reports.flatMap(r=>r.firedControlIds||[]).map(x=>x.replace(/#on[A-Z][\w$-]*$/,''))),gaps=reports.flatMap(r=>r.untaggedInteractive||[]);
const rows=inventory.controls.filter(x=>x.population==='comic-react'), byFile=new Map();for(const row of rows){const key=row.source_ref.path;(byFile.get(key)||byFile.set(key,[]).get(key)).push(row);}
const summary=(name,items)=>{const ids=items.map(x=>x.definition_id),ownGaps=gaps.filter(g=>g.nearest_control&&ids.includes(g.nearest_control));return{feature_file:name,inventory_count:ids.length,rendered_seen:ids.filter(x=>seen.has(x)).length,fired:ids.filter(x=>fired.has(x)).length,never_rendered:ids.filter(x=>!seen.has(x)),rendered_not_fired:ids.filter(x=>seen.has(x)&&!fired.has(x)),untagged_rendered:ownGaps};};
const files=[...byFile].sort(([a],[b])=>a.localeCompare(b)).map(([file,items])=>summary(file,items));
const applicability_rule={navigation_or_read_only:'normal and 10x history; cold and warm view; synchronization/catch-up; touch and keyboard where exposed; platform apply where platform-owned.',text_or_selection:'normal and 10x history; cold and warm view; synchronization/catch-up; repeated input; keyboard and touch variants; platform apply where exposed.',local_mutation:'normal and 10x history; cold and warm view; synchronization/catch-up; repeated input; offline and failing backend/recovery; touch and keyboard where exposed; platform apply where platform-owned.',permission_or_capability:'normal and 10x history where the screen contains history; cold and warm view; synchronization/catch-up; capability/permission boundary plus refusal/recovery; touch and keyboard where exposed; platform apply where platform-owned.',native_bridge:'native platform apply plus its applicable normal/10x, cold/warm, synchronization, offline/failing and input-mode dimensions.'};
const result={schema:'agentnet-interaction-reconciliation/v1',reports:reports.length,input_dispatch:[...new Set(reports.map(r=>r.inputDispatch))],comic_react:{total:summary('TOTAL',rows),by_feature_file:files},unattributed_untagged_rendered:gaps.filter(g=>!g.nearest_control),populations_without_rendered_binding:['overlay','standalone','static','native-desktop','native-android'],applicability_rule,notes:'Rendered presence is fixture reachability only. Fired records fixture-dispatched handlers only, not trusted Playwright input.'};
fs.writeFileSync(outFile,JSON.stringify(result,null,2)+'\n');
console.log(JSON.stringify({reports:reports.length,comic_inventory:rows.length,seen:result.comic_react.total.rendered_seen,fired:result.comic_react.total.fired,never_rendered:result.comic_react.total.never_rendered.length,rendered_not_fired:result.comic_react.total.rendered_not_fired.length,untagged:gaps.length}));
